document.addEventListener('DOMContentLoaded',()=>{const s=document.querySelector('.sidebar'),m=document.querySelector('#menuToggle');if(m)m.onclick=()=>s.classList.toggle('show');const q=document.querySelector('#tableSearch');if(q)q.oninput=()=>document.querySelectorAll('tbody tr').forEach(r=>r.style.display=r.innerText.toLowerCase().includes(q.value.toLowerCase())?'':'none');document.querySelectorAll('.js-confirm').forEach(b=>b.onclick=()=>toast(b.dataset.message||'Action completed successfully.'));});
function toast(msg,type='success'){const x=document.createElement('div');x.className='alert alert-'+type+' alert-dismissible fade show position-fixed top-0 end-0 m-3 shadow';x.style.zIndex=2000;x.innerHTML='<strong>'+msg+'</strong><button class="btn-close" data-bs-dismiss="alert"></button>';document.body.appendChild(x);setTimeout(()=>x.remove(),3000)}
function approveRow(b){b.closest('tr').remove();toast('Approval completed.')}function rejectRow(b){b.closest('tr').remove();toast('Request returned for revision.','warning')}
